            {/* Main VIP Card Container */}
            <div className="relative w-[calc(100%+1.5rem)] -ml-3 sm:w-full sm:mx-auto sm:max-w-[400px] filter drop-shadow-[0_10px_40px_rgba(0,0,0,0.8)] transition-transform hover:scale-[1.01] duration-500 perspective-1000 group rounded-[2rem] bg-[#0c0514] overflow-hidden border border-white/10">

                {/* Background Image Native Shape - Shorter height to crop empty bottom space */}
                <div className="relative w-full pt-[95%] sm:pt-[100%] bg-[#0c0514] overflow-hidden">
                    <img src="/digital-card/digitalcard-illa.webp?v=update9" alt="ILLA Exclusive Digital Card" className="absolute inset-0 w-full h-[120%] object-cover object-top pointer-events-none z-0 scale-[1.02] -translate-y-[8%]" />
                </div>

                {/* Sub-container for interactive/dynamic elements overlaying the image */}
                <div className="absolute inset-x-0 top-0 bottom-[120px] z-10 flex flex-col">

                    {/* QR Code Container - positioned over the white square on the webp art */}
                    <div className="absolute top-[37.2%] left-[51.5%] -translate-x-1/2 w-[35%] aspect-square flex items-center justify-center group/qr cursor-pointer">
                        {loading || !vip ? (
                            <div className="w-full h-full flex items-center justify-center bg-white/10 backdrop-blur-sm rounded-2xl">
                                <Loader2 size={24} className="animate-spin text-white/50" />
                            </div>
                        ) : (
                            <div className="w-full h-full flex items-center justify-center relative">
                                {/* Scroll-Reactive Glare Layer */}
                                <motion.div
                                    className="absolute inset-0 pointer-events-none z-20 mix-blend-overlay bg-gradient-to-r from-transparent via-white/80 to-transparent w-[150%] h-[150%] -rotate-45"
                                    style={{ x: glareX, y: glareY }}
                                />
                                <QrCodeCanvas value={`${origin}/vip/redeem?code=${vip.short_code}`} size={160} />
                            </div>
                        )}
                    </div>
                </div>

                {/* Bottom Area - Code & Expiration close to the CHAVE DE ACESSO text on webp art */}
                <div className="relative z-20 px-4 py-2 pb-6 flex flex-col justify-end bg-gradient-to-t from-[#0c0514] via-[#0c0514]/90 to-transparent -mt-[8rem]">
                    {/* Access Code Row */}
                    <div className="flex items-center justify-between mb-3 mt-4 px-4">
                        <span className="font-mono font-bold text-3xl tracking-[0.15em] text-white drop-shadow-md z-10">
                            {vip?.short_code ?? '••••••••'}
                        </span>
                        {vip && (
                            <button
                                onClick={() => copyToClipboard(vip.short_code, 'code')}
                                className="p-2 md:p-3 rounded-xl bg-white/5 hover:bg-white/15 border border-white/5 transition-all focus:scale-95 text-white/60 hover:text-white z-10 relative"
                                title="Copiar código"
                            >
                                {codeCopied ? <Check size={18} className="text-emerald-400" /> : <Copy size={18} />}
                            </button>
                        )}
                    </div>

                    {/* Footer Info Row */}
                    <div className="flex items-center justify-between text-[11px] md:text-xs text-white/50 px-2 relative z-10">
                        <div className="flex items-center gap-1.5 font-medium">
                            <Clock size={12} className="opacity-70" />
                            <span className="text-white/80 tracking-wide">{vip ? new Date(vip.expires_at).toLocaleDateString('pt-BR') : '--/--'}</span>
                        </div>
                        <div className="flex items-center gap-1.5 font-medium">
                            <QrCode size={12} className="opacity-70" />
                            <span>Uso presencial</span>
                        </div>
                    </div>
                </div>
            </div>

        </div>
    )
}

import { useState } from 'react'
import type { LeaderboardEntry } from '@/lib/gamification-types'
import { Trophy, Medal, ChevronRight } from 'lucide-react'
import FullRankingModal from './FullRankingModal'

interface Props {
    leaderboard: {
        top10: LeaderboardEntry[]
        user_position: number | null
    }
    currentUserId?: string
    currentUserXP?: number
}

function getRankIcon(rank: number) {
    if (rank === 1) return <Trophy size={16} className="text-illa-yellow drop-shadow-[0_2px_4px_rgba(245,158,11,0.5)]" />
    if (rank === 2) return <Medal size={16} className="text-gray-300 drop-shadow-[0_2px_4px_rgba(209,213,219,0.3)]" />
    if (rank === 3) return <Medal size={16} className="text-amber-600 drop-shadow-[0_2px_4px_rgba(217,119,6,0.3)]" />
    return <span className="text-xs font-black text-white/40 w-4 text-center">{rank}</span>
}

function getInitials(name: string | null): string {
    if (!name) return '?'
    return name.split(' ').map(w => w[0]).join('').toUpperCase().slice(0, 2)
}

export default function WeeklyLeaderboard({ leaderboard, currentUserId, currentUserXP }: Props) {
    const { top10, user_position } = leaderboard
    const [isModalOpen, setIsModalOpen] = useState(false)

    if (top10.length === 0) {
        return (
            <div className="rounded-2xl border border-dashed border-white/20 bg-white/5 p-5 text-center backdrop-blur-md">
                <Trophy size={20} className="mx-auto text-white/30 mb-1" />
                <p className="text-sm text-white/50 font-medium">Nenhuma atividade esta semana</p>
                <p className="text-xs text-white/30 mt-0.5">Complete missões para entrar no ranking!</p>
            </div>
        )
    }

    // Sync current user's XP if they are in the top 10
    const syncedTop10 = top10.map(entry => {
        if (currentUserId && entry.user_id === currentUserId && currentUserXP !== undefined) {
            return { ...entry, xp: currentUserXP }
        }
        return entry
    }).sort((a, b) => b.xp - a.xp).slice(0, 10) // Force Top 10 max

    return (
        <div className="space-y-3 relative group/ranking">
            {/* Ambient Background Glow matching Illa Exclusive */}
            <div className="absolute -inset-4 bg-gradient-to-br from-illa-pink/10 to-transparent blur-2xl pointer-events-none rounded-3xl" />

            <div className="flex items-center justify-between relative z-10">
                <h2 className="text-lg font-black text-white flex items-center gap-2 drop-shadow-md tracking-tight">
                    <Trophy size={20} className="text-illa-yellow drop-shadow-[0_0_10px_rgba(245,158,11,0.4)]" />
                    Ranking Semanal
                </h2>
                {user_position && user_position > 10 && (
                    <span className="text-xs font-bold text-white/70 bg-white/10 px-3 py-1.5 rounded-full border border-white/10 shadow-inner backdrop-blur-md shadow-black/20">
                        Você: #{user_position}
                    </span>
                )}
            </div>

            {/* Vitral Container */}
            <div className="rounded-[1.5rem] border border-white/10 bg-black/40 backdrop-blur-[20px] overflow-hidden shadow-[inset_0_1px_1px_rgba(255,255,255,0.05),0_10px_30px_rgba(0,0,0,0.5)] relative z-10 transition-colors duration-500 group-hover/ranking:border-white/20">
                {/* Surface Shine */}
                <div className="absolute inset-0 bg-gradient-to-br from-white/[0.08] to-transparent pointer-events-none" />

                <div className="relative z-10">
                    {syncedTop10.map((entry, i) => {
                        const rank = i + 1
                        const isCurrentUser = currentUserId === entry.user_id

                        return (
                            <div
                                key={entry.user_id}
                                className={`flex items-center gap-3 px-4 py-3 transition-colors ${i < syncedTop10.length - 1 ? 'border-b border-white/5' : ''
                                    } ${rank <= 3 ? 'bg-gradient-to-r from-amber-500/10 to-transparent' : 'hover:bg-white/[0.02]'
                                    }`}
                            >
                                <div className="w-6 flex justify-center flex-shrink-0">
                                    {getRankIcon(rank)}
                                </div>

                                <div className={`relative w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 border bg-gradient-to-br group ${rank === 1 ? 'from-amber-300 to-yellow-500 border-yellow-200 shadow-[0_0_10px_rgba(245,158,11,0.3)]' :
                                    rank === 2 ? 'from-gray-300 to-gray-400 border-gray-100' :
                                        rank === 3 ? 'from-amber-600 to-amber-700 border-amber-500' :
                                            'from-gray-800 to-gray-900 border-white/10'
                                    }`}>
                                    {entry.avatar_path ? (
                                        <img
                                            src={entry.avatar_path.startsWith('http')
                                                ? entry.avatar_path
                                                : `${process.env.NEXT_PUBLIC_SUPABASE_URL}/storage/v1/object/public/avatars/${entry.avatar_path}`}
                                            alt={entry.full_name || 'User'}
                                            onError={(e) => {
                                                e.currentTarget.style.display = 'none';
                                                e.currentTarget.parentElement?.classList.add('fallback-avatar');
                                            }}
                                            className="w-full h-full rounded-full object-cover shadow-inner"
                                        />
                                    ) : (
                                        <span className={`text-[10px] font-black ${rank <= 3 ? 'text-black/60' : 'text-white/50'}`}>
                                            {getInitials(entry.full_name)}
                                        </span>
                                    )}
                                    {/* Fallback Initial if image fails */}
                                    {entry.avatar_path && (
                                        <div className="hidden group-[.fallback-avatar]:flex absolute inset-0 items-center justify-center">
                                            <span className={`text-[10px] font-black ${rank <= 3 ? 'text-black/60' : 'text-white/50'}`}>
                                                {getInitials(entry.full_name)}
                                            </span>
                                        </div>
                                    )}
                                </div>

                                <div className="flex-1 min-w-0">
                                    <p className={`text-sm font-bold truncate ${isCurrentUser ? 'text-illa-pink' : 'text-white/90'}`}>
                                        {entry.full_name || 'Membro'}
                                        {isCurrentUser && <span className="ml-2 text-[8px] uppercase font-black bg-illa-pink text-white px-1 rounded-sm">Você</span>}
                                    </p>
                                </div>

                                <span className={`text-xs font-black flex-shrink-0 tabular-nums ${isCurrentUser ? 'text-white' : 'text-white/50'}`}>
                                    {entry.xp.toLocaleString('pt-BR')} XP
                                </span>
                            </div>
                        )
                    })}
                </div>

                {/* Botão Ver Ranking Completo */}
                <button
                    onClick={() => setIsModalOpen(true)}
                    className="w-full py-3.5 px-4 text-xs font-bold text-white/50 hover:text-white hover:bg-white/[0.04] transition-all flex items-center justify-center gap-1.5 uppercase tracking-wider relative z-10 border-t border-white/5 group/btn"
                >
                    Ver Ranking Completo
                    <ChevronRight size={14} strokeWidth={3} className="group-hover/btn:translate-x-1 transition-transform" />
                </button>
            </div>

            <FullRankingModal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                currentUserId={currentUserId}
            />
        </div>
    )
}

'use client'

import React, { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react'
import { AnimatePresence, motion } from 'framer-motion'
import { createSupabaseBrowser } from '@/lib/supabaseClient'

// Types
export type NotificationKind = 'mission_claim' | 'drop' | 'discount' | 'sorvetes_free' | 'system'

export interface CinematicToast {
    id: string
    title: string
    body: string
    kind: NotificationKind
    priority: number // 1=normal, 2=important, 3=win
}

interface CinematicToastContextType {
    showToast: (toast: Omit<CinematicToast, 'id'>) => void
    playSfx: (type: 'popup' | 'success' | 'error') => void
}

const CinematicToastContext = createContext<CinematicToastContextType | undefined>(undefined)

export const useCinematicToasts = () => {
    const context = useContext(CinematicToastContext)
    if (!context) {
        throw new Error('useCinematicToasts must be used within a CinematicToastProvider')
    }
    return context
}

// ------------------------------------------------------------------
// SFX Helper (Minimal - placeholder for now)
// ------------------------------------------------------------------
const playSound = (type: 'popup' | 'success' | 'error') => {
    // In a real app, load Audio objects here.
    // For MVP/Cinematic feel, we just log or try to play if file exists.
    // const audio = new Audio(`/sfx/${type}.mp3`)
    // audio.volume = 0.5
    // audio.play().catch(() => {}) 
    // (Disabled to avoid 404s until user adds files)
}

// ------------------------------------------------------------------
// Provider
// ------------------------------------------------------------------
export const CinematicToastProvider = ({ children }: { children: ReactNode }) => {
    const [queue, setQueue] = useState<CinematicToast[]>([])
    const [activeToast, setActiveToast] = useState<CinematicToast | null>(null)
    const [isPaused, setIsPaused] = useState(false)

    // Rate limit configuration
    const PROCESSING_INTERVAL = 15000 // 15s between toasts to avoid spam (premium feel)
    // If priority 3 (WIN), show immediately? Let's stick to queue for consistency, or bump to front.

    const showToast = useCallback((toastData: Omit<CinematicToast, 'id'>) => {
        const newToast = { ...toastData, id: Math.random().toString(36).substring(7) }

        setQueue(prev => {
            // Priority sort: higher priority comes first
            const newQueue = [...prev, newToast].sort((a, b) => b.priority - a.priority)
            return newQueue
        })
    }, [])

    // Register Service Worker
    useEffect(() => {
        if ('serviceWorker' in navigator) {
            navigator.serviceWorker.register('/sw.js')
                .then(registration => {
                    console.log('SW registered:', registration)
                })
                .catch(error => {
                    console.error('SW registration failed:', error)
                })
        }
    }, [])

    const playSfx = useCallback((type: 'popup' | 'success' | 'error') => {
        playSound(type)
    }, [])

    // Queue Processor
    useEffect(() => {
        if (activeToast || isPaused || queue.length === 0) return

        const nextToast = queue[0]
        setTimeout(() => {
            setActiveToast(nextToast)
            setQueue(prev => prev.slice(1))
        }, 0)

        // Play sound
        const sfxType = nextToast.priority >= 2 ? 'success' : 'popup'
        playSound(sfxType)

        // Auto dismiss logic
        const duration = nextToast.priority >= 3 ? 6000 : 4000
        const timer = setTimeout(() => {
            setActiveToast(null)
            // Wait a bit before processing next to breathe
            setIsPaused(true)
            setTimeout(() => setIsPaused(false), 2000)
        }, duration)

        return () => clearTimeout(timer)
    }, [queue, activeToast, isPaused])

    // ------------------------------------------------------------------
    // Render
    // ------------------------------------------------------------------
    return (
        <CinematicToastContext.Provider value={{ showToast, playSfx }}>
            {children}

            {/* TOAST CONTAINER */}
            <div className="fixed top-24 right-4 z-[9999] pointer-events-none flex flex-col items-end sm:top-6 sm:right-6">
                <AnimatePresence>
                    {activeToast && (
                        <ToastUI toast={activeToast} onClose={() => setActiveToast(null)} />
                    )}
                </AnimatePresence>
            </div>
        </CinematicToastContext.Provider>
    )
}

// ------------------------------------------------------------------
// UI Component
// ------------------------------------------------------------------
const ToastUI = ({ toast, onClose }: { toast: CinematicToast, onClose: () => void }) => {
    // Styling based on kind/priority
    const isWin = toast.priority >= 3

    return (
        <motion.div
            initial={{ opacity: 0, y: -20, scale: 0.9, filter: 'blur(10px)' }}
            animate={{ opacity: 1, y: 0, scale: 1, filter: 'blur(0px)' }}
            exit={{ opacity: 0, y: -20, scale: 0.9, filter: 'blur(10px)' }}
            transition={{ type: 'spring', stiffness: 400, damping: 25 }}
            className={`
                pointer-events-auto cursor-pointer relative overflow-hidden
                w-80 rounded-2xl p-4 shadow-2xl border
                backdrop-blur-xl bg-white/80 border-white/40
                dark:bg-black/60 dark:border-white/10
            `}
            onClick={onClose}
        >
            {/* Glow Effect */}
            <div className={`absolute inset-0 opacity-20 bg-gradient-to-br ${isWin ? 'from-yellow-400 to-pink-500' : 'from-blue-400 to-purple-500'}`} />

            {/* Sparkle (CSS only for now) */}
            {isWin && (
                <div className="absolute -top-10 -right-10 w-20 h-20 bg-white blur-xl opacity-40 animate-pulse" />
            )}

            <div className="relative flex gap-3 items-start">
                {/* Icon */}
                <div className={`
                    shrink-0 w-10 h-10 rounded-full flex items-center justify-center text-lg shadow-inner
                    ${isWin ? 'bg-gradient-to-br from-yellow-300 to-orange-400 text-white' : 'bg-gray-100 text-gray-600'}
                `}>
                    {getIcon(toast.kind)}
                </div>

                {/* Content */}
                <div className="flex-1 min-w-0">
                    <h4 className={`text-sm font-bold leading-tight mb-1 truncate ${isWin ? 'text-transparent bg-clip-text bg-gradient-to-r from-pink-600 to-purple-600' : 'text-gray-900 dark:text-white'}`}>
                        {toast.title}
                    </h4>
                    <p className="text-xs text-gray-600 dark:text-gray-300 leading-snug line-clamp-2">
                        {toast.body}
                    </p>
                </div>

                {/* Close X */}
                <button className="text-gray-400 hover:text-gray-600 transition-colors">
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                    </svg>
                </button>
            </div>

            {/* Progress Bar (optional, maybe too noisy for 'cinematic') */}
        </motion.div>
    )
}

function getIcon(kind: NotificationKind) {
    switch (kind) {
        case 'mission_claim': return '🎯'
        case 'drop': return '🎁'
        case 'discount': return '🏷️'
        case 'sorvetes_free': return '🍦'
        default: return '🔔'
    }
}

'use client'

import { Bell, Settings, X } from 'lucide-react'
import Link from 'next/link'
import { useEffect, useState, useRef } from 'react'
import { createSupabaseBrowser } from '@/lib/supabaseClient'
import { usePushNotifications } from '@/hooks/usePushNotifications'
import { AnimatePresence, motion } from 'framer-motion'

export function NotificationBell() {
    const [unreadCount, setUnreadCount] = useState(0)
    const [isOpen, setIsOpen] = useState(false)
    const popoverRef = useRef<HTMLDivElement>(null)

    const { isSupported, isSubscribed, loading, toggle } = usePushNotifications()
    const supabase = createSupabaseBrowser()

    const fetchCount = async () => {
        const { count, error } = await supabase
            .from('notifications')
            .select('*', { count: 'exact', head: true })
            .is('read_at', null)

        if (!error && count !== null) {
            setUnreadCount(count)
        }
    }

    useEffect(() => {
        setTimeout(() => fetchCount(), 0)
        let channel: ReturnType<typeof supabase.channel> | null = null

        const setupRealtime = async () => {
            const { data: { user } } = await supabase.auth.getUser()
            if (!user) return

            channel = supabase
                .channel(`notifications:${user.id}`)
                .on('postgres_changes', {
                    event: 'INSERT',
                    schema: 'public',
                    table: 'notifications',
                    filter: `user_id=eq.${user.id}`
                }, () => fetchCount())
                .subscribe()
        }

        setupRealtime()

        return () => {
            if (channel) supabase.removeChannel(channel)
        }
    }, [])

    // Close on click outside
    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (popoverRef.current && !popoverRef.current.contains(event.target as Node)) {
                setIsOpen(false)
            }
        }
        document.addEventListener('mousedown', handleClickOutside)
        return () => document.removeEventListener('mousedown', handleClickOutside)
    }, [])

    return (
        <div className="relative" ref={popoverRef}>
            <button
                onClick={() => setIsOpen(!isOpen)}
                className="relative p-2 rounded-full hover:bg-gray-100 transition-colors group mr-2 focus:outline-none"
            >
                <Bell size={20} className={`transition-colors ${isOpen ? 'text-illa-pink' : 'text-gray-400 group-hover:text-illa-pink'}`} />
                {unreadCount > 0 && (
                    <span className="absolute top-1 right-1 w-4 h-4 bg-illa-pink text-white text-[10px] font-bold flex items-center justify-center rounded-full border-2 border-white shadow-sm animate-pulse">
                        {unreadCount > 9 ? '9+' : unreadCount}
                    </span>
                )}
            </button>

            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: 10 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: 10 }}
                        transition={{ duration: 0.1 }}
                        className="absolute right-0 mt-2 w-72 bg-white rounded-2xl shadow-xl border border-gray-100 ring-1 ring-black/5 z-50 overflow-hidden"
                    >
                        <div className="p-4 border-b border-gray-50 flex items-center justify-between bg-gray-50/50">
                            <h3 className="font-bold text-gray-900 text-sm">Notificações</h3>
                            <button onClick={() => setIsOpen(false)} className="text-gray-400 hover:text-gray-900">
                                <X size={16} />
                            </button>
                        </div>

                        <div className="p-2">
                            {/* Push Toggle */}
                            {isSupported && (
                                <div className="flex items-center justify-between p-3 rounded-xl hover:bg-gray-50 transition-colors">
                                    <div className="flex flex-col">
                                        <span className="text-sm font-medium text-gray-700">Push Notifications</span>
                                        <span className="text-xs text-gray-500">
                                            {isSubscribed ? 'Ativado no dispositivo' : 'Receba no celular/PC'}
                                        </span>
                                    </div>
                                    <button
                                        onClick={toggle}
                                        disabled={loading}
                                        className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-illa-pink/20 ${isSubscribed ? 'bg-illa-pink' : 'bg-gray-200'
                                            }`}
                                    >
                                        <span
                                            className={`${isSubscribed ? 'translate-x-6' : 'translate-x-1'
                                                } inline-block h-4 w-4 transform rounded-full bg-white transition-transform`}
                                        />
                                    </button>
                                </div>
                            )}

                            <div className="h-px bg-gray-100 my-1" />

                            <Link
                                href="/members/notifications"
                                onClick={() => setIsOpen(false)}
                                className="flex items-center justify-between w-full p-3 rounded-xl hover:bg-gray-50 transition-colors group/link"
                            >
                                <span className="text-sm font-medium text-gray-700">Ver todas</span>
                                <div className="flex items-center gap-2">
                                    {unreadCount > 0 && (
                                        <span className="bg-illa-pink text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full">
                                            {unreadCount} novos
                                        </span>
                                    )}
                                    <Settings size={16} className="text-gray-400 group-hover/link:text-gray-900" />
                                </div>
                            </Link>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    )
}
